private void OnTriggerEnter(Collider other)
{
    // Start boss fight upon contact with player
    if (!_bossFightStarted && other.gameObject.name == "Player")
    {
        _bossFightStarted = true;
        _healthbarUI.SetActive(true);
        _bunnyAnimator.SetBool("waiting", false);

        Debug.Log("Start Boss Coroutine");
        StartCoroutine(ThrowRocks());
    }
}

private void HandlePhases()
{
    // === Phase 2 ===
    // In phase 2, the shield is activated and the carrots appear
    // You need to destroy the carrots to make the shield disappear
    if (CurrentHealth == 50f && !Fase2 && !Fase3)
    {
        Fase2 = true;
        _shield.SetActive(true);

        foreach (GameObject carrot in _carrots)
        {
            carrot.SetActive(true);
        }
    }

    // === Transition to Phase 3 ===
    // Once all carrots are destroyed, move to phase 3
    if (!Fase3 && _grapplingScript.DestroyedCarrots == 6)
    {
        Destroy(_shield);
        CurrentHealth = 30f;
        Fase3 = true;
    }

    // === Phase 3 Logic ===
    // In phase 3, the boss throws minions as the last attack every few seconds
    if (Fase3 && !_minionsSpawned)
    {
        Debug.Log("Starting the last Phase and sending minions!");
        _minionsSpawned = true;
        StartCoroutine(SpawnMinions());
    }
}

#region Coroutines
private IEnumerator ThrowRocks()
{
    // Keep throwing rocks as long as health is above 50%
    while (CurrentHealth > 50f)
    {
        Debug.Log("Throw rocks");
        Instantiate(_rockPrefab, _rockSpawnPoint.position, _rockSpawnPoint.rotation);
        yield return new WaitForSeconds(1f);
    }
}

private IEnumerator SpawnMinions()
{
    // Spawn minions as long as the boss is alive
    while (CurrentHealth > 0f)
    {
        Instantiate(_minionPrefab, _rockSpawnPoint.position, _rockSpawnPoint.rotation);
        Debug.Log("Minion spawned!");
        yield return new WaitForSeconds(2f);
    }
}
#endregion

private void StartGrapple()
{
    //check if you can grapple
    if (_grappleCooldownTimer > 0f) return;

    _isGrappling = true;
    //freeze the player so it doesn't cause any problems while grappling
    _characterMovement.currentState = CharacterMovement.PlayerState.Freeze;

    //draw a raycast to where you want to grapple
    RaycastHit hit;
    if (Physics.Raycast(_camera.position, _camera.forward, out hit, _maxGrappleDistance, _whatIsGrabbable))
    {
        _grapplePoint = hit.point;
        //dont allow to grapple the rock or boss
        if (hit.collider.CompareTag("rock"))
        {
            Invoke(nameof(StopGrapple), _grappleDelay);
        }
        else if (hit.collider.name == "Boss")
        {
            if (!_didBossDamage)
            {
                float damage = BossScript.CurrentHealth > 30f ? 5f : 1f;
                BossScript.CurrentHealth -= damage;
                _didBossDamage = true;
                BossExplode.Play();
            }
            Invoke(nameof(StopGrapple), _grappleDelay);
        }
        //destroy the boss carrot if you hit it
        else if (hit.collider.CompareTag("carrot"))
        {
            HandleCarrot(hit);
            Invoke(nameof(StopGrapple), _grappleDelay);
        }
        //if you hit an object you can actually grapple, then grapple movement = true
        else
        {
            _grappleMovement = true;
            _grappleCooldownTimer = 1f;
        }
    }
    else
    {
        //if you didn't hit anything / the raycast was too short to hit anything
        //draw a line
        _grapplePoint = _camera.position + _camera.forward * _maxGrappleDistance;
        //stop grappling
        Invoke(nameof(StopGrapple), _grappleDelay);
    }

    _lineRenderer.enabled = true;
    _lineRenderer.SetPosition(1, _grapplePoint);
}

private void ExecuteGrapple()
{
    //stop the body from moving
    _characterMovement.Rigidbody.isKinematic = true;
    //move the character to the grapple point
    _characterMovement.transform.position = Vector3.Lerp(
        _characterMovement.transform.position,
        _grapplePoint,
        Time.deltaTime * 2f
    );
    //if you are close enough to the grapple point stop grappling
    //cause the closer you get, the slower the grapple
    if (Vector3.Distance(_characterMovement.transform.position, _grapplePoint) < 0.7f)
    {
        StopGrapple();
    }
}

private void Update()
{
    _sceneName = SceneManager.GetActiveScene().name;
    //als je in een van de graaf scenes zit
    if ((_sceneName == "fossils" || _sceneName == "rocks" ) )
    {
        //vind de fossiel/steen  die gespawned is
        _gemObj = GameObject.Find("gem");
        _gemScipt = _gemObj.GetComponent<Stonerarity>();

        //als fossiel nog niet toegeveogd is 
        if (_fossilAdded == false && _gemObj.activeInHierarchy)
        {
            //haal de prefab van de steen of fossiel op
            FossilPrefabs.Add(_gemScipt.SelectedPrefab);
            _fossilAdded = true;
        }
    }
    else
    {
        //als je uit de graafscene bent zet fossiltoegevoegd of false
        //hierdoor kan je later weer een fossiel opgraven
        //en laten tonen op het algemene graafscherm
        _fossilAdded = false;
    }
    if(_sceneName == "SplashScreen")
    {
        //als je terug gaat naar menu 
        //haal alle stenen info weg
        DugUpRocks.Clear();
        NameOfRocks.Clear();
        FossilPrefabs.Clear();
    }

    if(_sceneName == "level 1")
    {

        //vind de opgegraven stenen doormiddel van de naam
        if(_rocksFound == false)
        {
            //zoek doormiddel van de namen de locaties van de gegraven stenen op
            foreach (string name in NameOfRocks)
            {
                DugUpRocks.Add(GameObject.Find(name));
            }
            _rocksFound = true;
        }
        //afhankelijk van welke hopen al gegraven zijn
        //spawn op elke hoop de juiste fossiel/steen prefab 
        //haal daarna de hopen weg
        for(int i = 0; i < DugUpRocks.Count; i++)
        {
            Instantiate(FossilPrefabs[i], DugUpRocks[i].transform.position, DugUpRocks[i].transform.rotation);
            Destroy(DugUpRocks[i]);
        }
        DugUpRocks.Clear();
    }
    else
    {
        //maak de lijst schoon zodat het geen probelemen veroorzaakt in lvl1
        RockChosen = false;
        DugUpRocks.Clear();
        _rocksFound= false;
    }
}

private void CheckForTouchInput()
{   
    //kijk of er getikt is op het scherm
    if (Input.touchCount > 0)
    {
        Touch touch = Input.GetTouch(0);
        if (touch.phase == UnityEngine.TouchPhase.Began)
        { 
            //haal positie van touch op en stuur een raycast ernaartoe
            DetectObject(touch.position);
        }
    }
    //kijk of er geklikt is op het scherm
    if (Input.GetMouseButtonDown(0))
    {
        //haal de positie op van de klik en stuur een raycast ernaartoe
        DetectObject(Input.mousePosition);
    }
}
